/* Fleet button busy helper (`runBusy`).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Pairs with button.css's
 * `[aria-busy="true"]` look and the sibling `toast` component, which an app
 * vendors beside `button/`.
 *
 * One tap, one run: while `work` is in flight the button is busy (spinner,
 * dimmed, no taps) and a second call for the same button is ignored. Busy is
 * cleared in `finally`, so a failing run never leaves a dead button. The
 * outcome goes to the toast: an optional message when it starts, one on
 * success, one on failure with the error's own text.
 */

'use strict';

import { showToast, hideToast } from '../toast/toast.js';

/** The text of whatever `work` threw. */
function errorText(err) {
  if (err && typeof err.message === 'string' && err.message) return err.message;
  return err == null ? 'Something went wrong' : String(err);
}

/**
 * Run a slow action behind a busy button.
 *
 * @param {HTMLElement} button  the control that was tapped.
 * @param {() => any} work      the slow action; may be async or throw.
 * @param {{start?: string,
 *          done?: string | ((value: any) => string),
 *          fail?: string | ((err: any) => string),
 *          host?: HTMLElement}} [opts]
 *        `start` is a toast shown while the work runs (kept until the outcome
 *        replaces it). `done` is the success toast, or a function of the
 *        result. `fail` is the lead text of the failure toast, which always
 *        carries the error's message after it ("Refresh failed: timeout");
 *        a function builds the whole text. A failure always toasts, even with
 *        no `fail`. `host` is a sheet's own toast element, as for `showToast`.
 * @returns {Promise<{ok: boolean, value?: any, error?: any, ignored?: boolean}>}
 *        never rejects: `ok: false` with `error` when the work failed, or with
 *        `ignored: true` when the button was already busy and nothing ran.
 */
export async function runBusy(button, work, opts) {
  if (button.getAttribute('aria-busy') === 'true') return { ok: false, ignored: true };
  const o = opts || {};
  const host = o.host ? { host: o.host } : undefined;
  button.setAttribute('aria-busy', 'true');
  let started = false;
  try {
    if (o.start) { showToast(o.start, undefined, { ms: 0, ...host }); started = true; }
    const value = await work();
    if (o.done) {
      showToast(typeof o.done === 'function' ? o.done(value) : o.done, undefined, host);
    } else if (started) {
      hideToast(o.host);
    }
    return { ok: true, value };
  } catch (error) {
    const text = typeof o.fail === 'function'
      ? o.fail(error)
      : (o.fail ? o.fail + ': ' : '') + errorText(error);
    showToast(text, 'error', host);
    return { ok: false, error };
  } finally {
    button.removeAttribute('aria-busy');
  }
}
